// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2007, "2-3", [{"author":"И. Рубанов","question":"С какой буквы не могут начинаться слова?","choices":["<em>Й</em>","<em>Ё</em>","<em>Щ</em>","<em>Ь</em>","<em>Э</em>."],"key":"Г","review":["Первая буква слова","Подбери пример к каждой букве: «йод», «ёлка», «щука», «эхо». Все эти буквы могут стоять первыми.","Мягкий знак ставят после согласной, чтобы показать мягкость или разделить буквы. В самом начале слова ему не за чем стоять."]},{"author":"О. Шеманаева","question":"Век — это промежуток времени длиной в …","choices":["50 лет","100 лет","500 лет","1000 лет","5000 лет."],"key":"Б","review":["Сколько длится век?","Сравни «век» и «столетие». Слово «столетие» подсказывает число лет своей первой частью.","Один век равен ста годам. Например, от 1901 до 2000 года включительно прошёл двадцатый век."]},{"author":"Е. Вельмезова","question":"Каким из указанных ниже слов человек обычно <strong>не</strong> обращается к животным?","choices":["<em>тпру</em>","<em>цып-цып</em>","<em>ау</em>","<em>кис-кис</em>","<em>но.</em>"],"key":"В","review":["Как подзывают животных","Проверь, к кому обращаются: «тпру» и «но» говорят лошади, «цып-цып» — курам, «кис-кис» — кошке.","«Ау!» кричат, чтобы люди отозвались, например в лесу. Это слово обычно не говорит животному, что делать."]},{"author":"О. Серебренников","question":"В какой паре второе слово называет пряность, которую получают из коры некоторых деревьев?","choices":["<em>лиса — лисица</em>","<em>роща — рощица</em>","<em>вода — водица</em>","<em>кора — корица</em>","<em>лужа — лужица</em>."],"key":"Г","unrated":false,"reviewedEdition":true,"review":["Значения пары слов","В парах «вода — водица» и «лужа — лужица» вторые слова называют воду и лужу. В парах про лису и рощу тоже нет названия пряности.","Корица — пряность из высушенной коры коричного дерева. Подходит пара «кора — корица»."]},{"author":"О. Шеманаева","question":"Закончите фразу «<em>Ах ты, горе …!</em>»","choices":["<em>бобовое</em>","<em>фасолевое</em>","<em>чечевичное</em>","<em>гороховое</em>","<em>луковое</em>."],"key":"Д","review":["Ах ты, горе…","Представь, что кто-то сделал простую работу неумело. О нём могут сказать «ах ты, горе …» в шутку или с досадой.","Привычное выражение — «горе луковое». В нём используется прилагательное от слова «лук»."]},{"author":"Е. Вельмезова и И. Иткин","question":"К Лене и её восьмилетнему сыну Мише приехала подруга из Франции. Через несколько дней она удивлённо спросила у Лены: «Почему ты называешь своего сына женским именем?» Как же Лена называла Мишу?","choices":["<em>СОНЯ</em>","<em>ЛИЗА</em>","<em>ПОЛЯ</em>","<em>ВЕРА</em>","<em>НАТАША</em>."],"key":"А","review":["Как мама звала Мишу?","Мама могла употребить слово о привычке сына. Вспомни, как можно назвать человека, который любит долго спать.","Любителя поспать зовут «соня». Подруга услышала в этом слове женское имя Соня, хотя его можно сказать и про мальчика."]},{"author":"О. Баженова","question":"Посмотрите на слова <em>дупло, улей, нора, берлога</em> и решите, кто лишний:","choices":["<em>медведь</em>","<em>пчела</em>","<em>орёл</em>","<em>белка</em>","<em>лиса.</em>"],"key":"В","review":["Жилища животных","Подбери жильцов: в берлоге зимует медведь, в улье живут пчёлы, в дупле — белка, в норе — лиса.","Орёл строит гнездо. Гнезда в списке жилищ нет, поэтому лишний — орёл."]},{"author":"И. Рубанов","question":"Благодаря какому оружию появилось слово <em>стрелять</em>?","choices":["ружью","пушке","мушкету","дубинке","луку."],"key":"Д","review":["Откуда слово «стрелять»?","Найди родственное слово «стрела». Как назывался снаряд до появления пуль и ядер?","Стрелы выпускают из лука. Поэтому слово «стрелять» связано с луком, а уже потом его стали употреблять и о другом оружии."]},{"author":"И. Иткин","question":"«<em>— Какая тебе разница, об чего я порезался? — сказал Крот, от боли забывая, как надо говорить правильно</em>» (К. Грэм, «Ветер в ивах», перевод И. Токмаковой). А как надо было бы сказать правильно?","choices":["<em>о чего</em>","<em>о что</em>","<em>об что</em>","<em>обо что</em>","<em>о чём</em>."],"key":"Г","review":["Как порезался Крот?","В сочетании «порезаться … что?» говорим о предмете, которого коснулись. Можно порезаться «о стекло» или «об острый край».","С местоимением «что» употребляют форму «обо что»: «Обо что ты порезался?» «О чём?» подошло бы к вопросу о теме разговора или размышления."]},{"author":"М. Кронгауз","question":"Только одно из приведённых ниже названий цветов <strong>не</strong> обозначает оттенка красного. Какое?","choices":["<em>алый</em>","<em>лазурный</em>","<em>вишнёвый</em>","<em>багровый</em>","<em>пурпурный</em>."],"key":"Б","review":["Пять названий цветов","Представь алый мак, тёмную вишню, багровый закат и пурпурную ткань. Эти цвета близки к красному.","Лазурный — голубой или яркий синий, как ясное небо. Этот цвет выбивается из ряда."]},{"author":"И. Иткин","question":"В стихотворении Владимира Маяковского «Приказ по армии искусства» читаем:\n<em>Есть ещё хорошие буквы:</em>\n<em>Эр,</em>\n<em>Ша,</em>\n<em>Ща.</em>\nКакие буквы названы в стихотворении неправильно?","choices":["только <em>р</em>","только <em>ш</em>","только <em>щ</em>","<em>ш</em> и <em>щ</em>","все буквы названы правильно."],"key":"Д","review":["Буквы у Маяковского","Проверь, как называют сами буквы в алфавите. У р имя «эр», у ш — «ша», у щ — «ща».","Все три названия совпадают со стихотворением. Если бы нужно было назвать звуки, их произнесли бы без добавочных гласных."]},{"author":"И. Иткин","question":"В рассказе А. П. Чехова «Детвора» дети играют в лото. Некоторые числа, встречающиеся в игре, имеют специальные образные названия: «кочерга», «палочки», «Семён Семёныч», «дедушка». Выберите вариант, где эти числа приведены в том же порядке, в котором идут их названия.","choices":["2, 10, 7, 9","7, 11, 77, 90","7, 11, 17, 99","2, 77, 17, 90","2, 77, 7, 99."],"key":"Б","review":["Числа из игры в лото","Посмотри на очертания цифр. Семёрка напоминает кочергу, а две единицы — две палочки. Значит, нужны 7 и 11 в начале.","В лото «Семён Семёныч» — двойная семёрка, 77. «Дедушка» — самое большое число на бочонках, 90. Весь порядок — 7, 11, 77, 90."]},{"author":"Е. Муравенко","question":"В каком из слов два слога?","choices":["<em>строй</em>","<em>сарай</em>","<em>всплеск</em>","<em>ария</em>","<em>наука</em>."],"key":"Б","review":["Сколько слогов в слове?","Посчитай гласные буквы. В «строй» и «всплеск» по одной, в «ария» и «наука» по три. Буква й слога не образует.","В «сарай» две гласные а, поэтому два слога: «са-рай»."]},{"author":"И. Иткин","question":"В каком из этих предложений первое слово нельзя, не изменяя его, переставить в конец так, чтобы предложение осталось правильным?","choices":["<em>Театров в городе было много</em>.","<em>Театров в городе было множество</em>.","<em>Театров в городе было четыре</em>.","<em>Театров в городе было пять</em>.","<em>Театров в городе не было</em>."],"key":"В","review":["Театры в городе","Переставь «театров» в конец. Получаются нормальные сочетания «много театров», «множество театров», «пять театров» и «не было театров».","После «четыре» здесь нужна форма «театра»: «в городе было четыре театра». С неизменным словом «театров» так сказать нельзя."]},{"author":"Л. Фёдорова","question":"В каком слове нет приставки <strong><em>у-</em></strong>?","choices":["<em>ушат</em>","<em>укус</em>","<em>ушиб</em>","<em>укол</em>","<em>ухват</em>."],"key":"А","review":["Слова на букву у","Подбери близкие глаголы: укус от «укусить», ушиб от «ушибить», укол от «уколоть», ухват от «ухватить». Начальное у здесь стоит перед корнем.","Ушат — ёмкость с ручками, или ушами. Начальное у входит в корень, поэтому приставки у- у этого слова нет."]},{"author":"Л. Фёдорова","question":"Какое слово <strong>не</strong> обозначает растение?","choices":["<em>калина</em>","<em>малина</em>","<em>рябина</em>","<em>смородина</em>","<em>виноградина</em>."],"key":"Д","review":["Растение или ягода","Малина, калина, рябина и смородина могут называть и само растение, и его плоды. Проверь, о чём говорят «береги» или «посади».","Виноградина — одна ягода винограда. У растения название «виноград», поэтому «виноградина» выделяется."]},{"author":"И. Рубанов","question":"Петя весит меньше Васи. Четыре их одноклассника высказались об этом так:\n— <em>вес Пети легче Васи</em>;\n— <em>Петя легче Васи</em>;\n— <em>вес Пети легче веса Васи</em>;\n— <em>Петя легче веса Васи</em>.\nСколько здесь правильных фраз?","choices":["все четыре","три","две","одна","ни одной."],"key":"Г","review":["Кто легче?","Сравнивать по весу можно двух людей. В двух фразах сравниваются разные вещи: сам человек и число, которое показывает его вес.","Правильно «Петя легче Васи». Если сравнивать именно вес, говорят «вес Пети меньше веса Васи». Из данных фраз подходит одна."]},{"author":"Л. Фёдорова","question":"О каком человеке говорят, что ему «<em>медведь на ухо наступил</em>»?","choices":["о косолапом","о кривом","о лопоухом","о тугоухом","о лишённом музыкального слуха."],"key":"Д","review":["Медведь и ухо","Вспомни, что позволяет различать высоту звуков и верно повторять мелодию. Это называется музыкальным слухом.","«Медведь на ухо наступил» говорят о человеке, которому трудно различать и точно петь ноты. Выражение касается музыкального слуха."]},{"author":"Е. Муравенко","question":"Из всех приведённых ниже слов, кроме одного, можно убрать один слог так, чтобы получилось новое слово. Кроме какого?","choices":["<em>золото</em>","<em>серебро</em>","<em>железо</em>","<em>листопад</em>","<em>корзинка</em>."],"key":"Г","review":["Убери целый слог","Убирай по одному слогу. Из «зо-ло-то» выйдет «лото», из «се-ре-бро» — «ребро», из «же-ле-зо» — «желе», из «кор-зин-ка» — «корка».","В слове «ли-сто-пад» можно убрать первый слог, средний или последний. «Стопад», «липад» и «листо» не дают известного русского слова. Поэтому лишнее слово — «листопад»."]},{"author":"Е. Муравенко","question":"Даны слова: <em>птен_чик</em>, <em>камен_щик</em>, <em>ноч_ной</em>, <em>печ_ка</em>. В скольких из них на месте пропуска следует вставить <strong><em>ь</em></strong>?","choices":["ни в одном","в одном","в двух","в трёх","во всех четырёх."],"key":"А","review":["Нужен ли мягкий знак?","Посмотри на два согласных у пропуска. В «птенчик» рядом нч, в «каменщик» — нщ.","В «ночной» и «печка» есть чн и чк. В этих четырёх сочетаниях ь не пишется, значит, вставлять его не надо ни разу."]},{"author":"Школьные учителя","question":"Даны пары слов:\n1) <em>стог</em> — <em>сток</em>, 2) <em>шёл</em> — <em>шов</em>,\n3) <em>сор</em> — <em>сыр</em>, 4) <em>мать</em> — <em>мять</em>.\nВ каких парах произношение слов различается ровно одним звуком?","choices":["в 1, 2","в 1, 3","в 2, 3, 4","в 1, 3, 4","во всех."],"key":"В","review":["Один звук меняется","Произнеси «стог — сток»: на конце обоих слышно [к], поэтому разницы нет. В паре «шёл — шов» меняется только последний звук, [л] на [ф].","В «сор — сыр» меняется гласный, а в «мать — мять» — твёрдый [м] на мягкий [м’]. Подошли пары 2, 3 и 4."]},{"author":"К. Кноп","question":"В словесной игре «цепочки», придуманной Льюисом Кэрроллом, требуется превращать одно слово в другое, меняя по одной букве так, чтобы все промежуточные результаты тоже были осмысленными словами. Например, <strong><em>век</em></strong> превращается в <strong><em>лес</em></strong> за два хода: <strong><em>век</em></strong> — <strong><em>вес</em></strong> — <strong><em>лес</em></strong>. В какой из следующих цепочек первое слово <strong>не</strong> превращается во второе за два хода?","choices":["<em>аист</em> — <em>лифт</em>","<em>барон</em> — <em>бутон</em>","<em>река</em> — <em>щука</em>","<em>корона</em> — <em>ворота</em>","<em>ворон</em> — <em>город.</em>"],"key":"Д","review":["Два хода в словах","Меняй по одной букве и проверяй промежуточное слово. Получаются «аист — лист — лифт», «барон — батон — бутон», «река — рука — щука» и «корона — ворона — ворота».","У «ворон» и «город» различаются только первая и последняя буквы. После одного нужного изменения вышло бы «горон» или «вород». Ни одного такого слова нет, значит, в два хода не получится."]},{"author":"И. Рубанов","question":"«Ойл» по-английски означает ‘нефть’. С какими тремя сибирскими городами связано возникновение нефтяной компании ЛУКОЙЛ?","choices":["Когалым, Лангепас, Надым","Надым, Сургут, Урай","Лангепас, Сургут, Урай","Когалым, Надым, Сургут","Когалым, Лангепас, Урай."],"key":"Д","review":["Города в названии компании","Выдели в названии «ЛУКОЙЛ» английскую часть «ойл». Остаются три буквы Л, У, К.","Они стоят в начале названий Лангепаса, Урая и Когалыма. Только в одном варианте названы все три города."]},{"author":"К. Кноп","question":"В каждом из приведённых словосочетаний пропущены гласные буквы. Во всех ответах, кроме одного, одно из слов означает цвет, а другое — предмет мебели. Для какого ответа это правило нарушено?","choices":["<em>БЛЙ ДВН</em>","<em>ЗЛН ПРТ</em>","<em>ЧРН КРСЛ</em>","<em>СН МР</em>","<em>СРЙ СТЛ.</em>"],"key":"Г","review":["Догадайся по согласным","Вставь гласные в четыре сочетания: белый диван, зелёная парта, чёрное кресло, серый стол. В каждом есть цвет и мебель.","«СН МР» читается как «синее море». «Синее» обозначает цвет, а море — водоём, поэтому этот вариант отличается."]},{"author":"И. Рубанов","question":"Вот три фразы:\n1) <em>Судно причалило в порту Одессы</em>.\n2) <em>Судно причалило на порту Одессы</em>.\n3) <em>Судно причалило к порту Одессы</em>.\nВ каких из них предлог употреблён правильно?","choices":["только в 2 и 3","только в 1 и 3","только в 1 и 2","только в 1","только в 3."],"key":"Г","review":["Судно в Одессе","Различи место и точку, к которой подходит судно. Место — «в порту», а чтобы назвать точку швартовки, говорят «к причалу» или «к берегу».","В этих фразах назван порт как место: «Судно причалило в порту Одессы». В обычной речи подходит только первое предложение."]},{"author":"И. Иткин и методкомиссия","question":"Как можно правильно продолжить фразу: <em>У Маши есть книжка и карандаш, а у Даши — много…</em>?","choices":["<em>книжек и карандашов</em>","<em>книжков и карандашей</em>","<em>книжк и карандашей</em>","<em>книжек и карандаш</em>","ни один из ответов (А)–(Г) не может быть правильным продолжением этой фразы."],"key":"Г","review":["Что есть у Даши?","После «много» нужны формы «книжек» и «карандашей». Такой пары в ответах нет, но слово «много» может относиться лишь к книжкам.","Подставь пропущенное «есть»: «У Даши есть много книжек и карандаш». У неё много книжек и один карандаш, поэтому продолжение «книжек и карандаш» подходит."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
